input.command:
Set-Location F:\CraftAnything\everything\app\dotnet
Move-Item OmniFind QuickFind -ErrorAction Stop
Set-Location QuickFind
# text files only, outside build folders
$files = Get-ChildItem -Recurse -File | Where-Object { $_.FullName -notmatch '\\(bin|obj|\.vs)\\' -and $_.Extension -in '.cs','.xaml','.csproj','.slnx','.iss','.ps1','.json','.manifest','.py','.user' }
foreach ($f in $files) {
  $t = [System.IO.File]::ReadAllText($f.FullName)
  $n = $t -replace 'OmniFind','QuickFind' -replace 'omnifind','quickfind'
  if ($n -ne $t) { [System.IO.File]::WriteAllText($f.FullName, $n, (New-Object System.Text.UTF8Encoding($true))) }
}
Get-ChildItem -Recurse -File | Where-Object { $_.FullName -notmatch '\\(bin|obj|\.vs)\\' -and $_.Name -like '*OmniFind*' } | ForEach-Object { Rename-Item $_.FullName ($_.Name -replace 'OmniFind','QuickFind') }
Get-ChildItem -Recurse -File | Where-Object { $_.FullName -notmatch '\\(bin|obj|\.vs)\\' } | Where-Object { $_.Name -match 'mni' } | Select-Object FullName
Get-ChildItem -File | Select-Object Name
Select-String -Path *.csproj -Pattern "QuickFind" | Select-Object -First 5 | ForEach-Object Line
